SELECT DISTINCT v.model_year, v.powertrain
FROM gishub.fleet.vehicles v
ORDER BY v.model_year DESC, v.powertrain;

SELECT
  100.0 * SUM(CASE WHEN location_type = 'public_dc' THEN energy_kwh ELSE 0 END) / SUM(energy_kwh) AS pct_energy_public_dc
FROM gishub.fleet.charging_sessions;

SELECT
  100.0 * SUM(CASE WHEN location_type = 'public_dc' THEN energy_kwh ELSE 0 END) / NULLIF(SUM(energy_kwh), 0) AS pct_energy_public_dc
FROM gishub.fleet.charging_sessions;
